void Command_04(CommandInfo* info)
{
    const u32 counter_index = info->loop_count - 1;
    const u32 return_index = info->loop_count - 2;
    u32 remaining =
        (u32) (uintptr_t) info->event_return[counter_index] - 1;

    info->event_return[counter_index] =
        (union CmdUnion*) (uintptr_t) remaining;
    if ((s32) remaining != 0) {
        info->u = info->event_return[return_index];
        return;
    }
    NEXT_CMD(info);
    info->loop_count -= 2;
}
